 c.retry=!!(c.req.allowed&&temp&&retries>0&&!c.control.stop_new_authors&&Date.now()+wait+c.req.timeout+c.req.reserve<=c.deadline&&(c.req.kind!=='gemini'||c.limits.max_gemini_requests_per_step>=2));
